contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d1, uint d2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d1) + (d2)); require(d1 <= 1000000000000000000000000000000); require(d2 <= 1000000000000000000000000000000);
        require(d1 > 0 && d2 > 0);
        require(address(this).balance >= d1 + d2);
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Deposit{value: d1}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: d2}(); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        assert(balAfter == balBefore + d1 + d2 && ethAfter == ethBefore + d1 + d2);
    }
    receive() external payable {}
}

